using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Threading;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows.Forms;
namespace GearLab {
 public static class CADStudioTests {
  static int checks;static void Check(bool value,string name){checks++;if(!value)throw new Exception(name);}static void Near(double actual,double expected,string name,double tolerance=1e-5){Check(Math.Abs(actual-expected)<=tolerance*Math.Max(1,Math.Abs(expected)),name+": "+actual+" != "+expected);}
  static CADFeature Box(){var f=CADTools.Feature("box");f.Id="box";return f;}static CADDocument One(CADFeature f){var d=new CADDocument();d.Features.Add(f);return d;}
  static void Wait(Func<bool> condition,string name){var time=System.Diagnostics.Stopwatch.StartNew();while(!condition()&&time.Elapsed.TotalSeconds<90){Application.DoEvents();Thread.Sleep(10);}Check(condition(),name);}
  public static int Run(string folder){Directory.CreateDirectory(folder);var report=new StringBuilder();try{using(var kernel=new CADKernel()){
   var doc=One(Box());var result=kernel.Run(doc);Near(result.Bodies[0].Volume,24000,"exact B-rep box volume");Check(result.Bodies[0].Faces.Count==6&&result.Bodies[0].Edges.Count==12,"B-rep face and edge selection maps");result.Bodies[0].ReadMesh();Near(Math.Abs(result.Bodies[0].Display.SignedVolume()),24000,"view triangulation volume");Check(result.Bodies[0].TriangleFaces.All(f=>f>=0&&f<6),"triangle-to-face map");
   foreach(string kind in new[]{"fillet","chamfer","shell","presspull","draft","split","linear_pattern","circular_pattern","mirror","scale","move"}){var copy=doc.Clone();var f=CADTools.Feature(kind);f.Target="box";if(kind=="fillet"||kind=="chamfer")f.Edges.Add(0);if(kind=="shell"||kind=="presspull")f.Faces.Add(5);if(kind=="draft")f.Faces.Add(0);if(kind=="split"){f.Values["Plane"]="XY";f.Values["Z"]="10";}if(kind=="move")f.Values["X"]="12";copy.Features.Add(f);var built=kernel.Run(copy);Check(built.Bodies.Count>0,"native operation "+kind);if(kind=="presspull")Near(built.Bodies[0].Volume,30000,"face push adds correct volume");if(kind=="shell")Near(built.Bodies[0].Volume,7152,"open shell volume");if(kind=="split")Near(built.Bodies.Sum(b=>b.Volume),24000,"split conserves volume");}
   doc.Parameters["height"]="20";doc.Features[0].Values["Height"]="height";var hole=CADTools.Feature("hole");hole.Target="box";hole.Faces.Add(5);hole.Point=new[]{15.0,15.0,20.0};hole.Values["Diameter"]="6";hole.Values["Through"]="true";doc.Features.Add(hole);result=kernel.Run(doc);Near(result.Bodies[0].Volume,24000-Math.PI*9*20,"through hole volume");doc.Parameters["height"]="30";result=kernel.Run(doc);Near(result.Bodies[0].Volume,36000-Math.PI*9*30,"history edit updates hole face position");string step=Path.Combine(folder,"cad-editable.step");kernel.Run(doc,"export_step",step);Check(File.ReadAllText(step).Contains("MANIFOLD_SOLID_BREP"),"native STEP export");var imported=CADDocument.ImportStep(File.ReadAllBytes(step),"Imported");var ir=kernel.Run(imported);Near(ir.Bodies[0].Volume,result.Bodies[0].Volume,"STEP import volume roundtrip");var top=ir.Bodies[0].Faces.Where(f=>f.Kind=="plane"&&f.Normal.Length==3&&f.Normal[2]>.9).OrderByDescending(f=>f.Center[2]).First();var push=CADTools.Feature("presspull");push.Target=imported.Features[0].Id;push.Faces.Add(top.Id);push.Values["Distance"]="5";imported.Features.Add(push);var after=kernel.Run(imported);Near(after.Bodies[0].Volume,(1200-Math.PI*9)*35,"imported STEP remains editable");imported.Save(Path.Combine(folder,"imported-edited.cad.json"));kernel.Run(imported,"export_step",Path.Combine(folder,"imported-edited.step"));
   var sketchFeature=new CADFeature{Kind="sketch",Name="Driven sketch",Sketch=new CADSketch()};var circle=new CADEntity{Kind="circle",Radius="diameter/2"};circle.Points.Add(new[]{0.0,0.0});sketchFeature.Sketch.Entities.Add(circle);var sketchDoc=new CADDocument();sketchDoc.Parameters["diameter"]="20";sketchDoc.Features.Add(sketchFeature);var extrusion=CADTools.Feature("extrude");extrusion.Sketches.Add(sketchFeature.Id);extrusion.Values["Distance"]="10";sketchDoc.Features.Add(extrusion);Near(kernel.Run(sketchDoc).Bodies[0].Volume,Math.PI*1000,"sketch circle extrudes");sketchDoc.Parameters["diameter"]="30";Near(kernel.Run(sketchDoc).Bodies[0].Volume,Math.PI*2250,"parameter drives sketch and body");var solved=kernel.Run(new CADDocument(),"solve_sketch",null,null,null,new Dictionary<string,object>{{"Sketch",sketchFeature.Sketch},{"Parameters",sketchDoc.Parameters}});Check(solved.Sketch.Entities[0].Radius=="diameter/2","constraint solve preserves named radius expression");
   var lines=new CADSketch();var line=new CADEntity{Kind="line",Points=new List<double[]>{new[]{0.0,0.0},new[]{10.0,2.0}}};lines.Entities.Add(line);lines.Constraints.Add(new CADConstraint{Kind="horizontal",A=line.Id});lines.Constraints.Add(new CADConstraint{Kind="length",A=line.Id,Value="20"});solved=kernel.Run(new CADDocument(),"solve_sketch",null,null,null,new Dictionary<string,object>{{"Sketch",lines}});Near(solved.Sketch.Entities[0].Points[0][1],solved.Sketch.Entities[0].Points[1][1],"horizontal constraint solved");Near(solved.ConstraintStatus["Error"],0,"constraint residual");lines.Constraints.Add(new CADConstraint{Kind="length",A=line.Id,Value="30"});bool conflict=false;try{kernel.Run(new CADDocument(),"solve_sketch",null,null,null,new Dictionary<string,object>{{"Sketch",lines}});}catch{conflict=true;}Check(conflict,"contradictory dimensions rejected");
   var reportGears=new StringBuilder("Пресет;Объём мм3;Грани\r\n");foreach(var preset in CADGearCatalog.All){var f=new CADFeature{Kind="gear",Name=preset.Name,Values=new Dictionary<string,string>(preset.Values)};var gd=One(f);var built=kernel.Run(gd);Check(built.Bodies.Count==1&&built.Bodies[0].Volume>0,"gear preset "+preset.Name);reportGears.AppendLine(preset.Name+";"+Engine.N(built.Bodies[0].Volume)+";"+built.Bodies[0].Faces.Count);if(preset==CADGearCatalog.All[0]||preset.Values["Type"]=="herringbone"&&preset.Values["Teeth"]=="20"){kernel.Run(gd,"export_step",Path.Combine(folder,preset.Values["Type"]+".step"));gd.Save(Path.Combine(folder,preset.Values["Type"]+".cad.json"));}}File.WriteAllText(Path.Combine(folder,"gear-presets.csv"),reportGears.ToString(),new UTF8Encoding(true));report.AppendLine("PASS exact B-rep operations, import/edit/export STEP, parameter rebuild, sketch constraints and "+CADGearCatalog.All.Count+" gear presets.");
   CADBridgeTests.Run(kernel,folder);report.AppendLine("PASS native robot and mechanism geometry, mass, placement and mixed STEP assembly.");var saved=doc.Serialize();Check(CADDocument.Parse(saved).Serialize()==saved,"CAD project self-contained roundtrip");var suppression=One(Box());suppression.Features[0].Suppressed=true;var dependent=CADTools.Feature("fillet");dependent.Target="box";dependent.Edges.Add(0);suppression.Features.Add(dependent);Check(kernel.Run(suppression).Bodies.Count==0,"suppression cascades to dependent operation");}
   using(var form=new CADStudioForm(CADDocument.Example(),null)){form.Show();Wait(()=>form.State!=null&&form.Scene.Ready,"native CAD UI ready");using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(0,0,bitmap.Width,bitmap.Height));bitmap.Save(Path.Combine(folder,"cad-ui.png"));}form.Scene.SavePng(Path.Combine(folder,"cad-model.png"),1100,750);form.ApproveTestClose();form.Close();}report.AppendLine("PASS native CAD Studio window and viewport.");report.AppendLine("PASS "+checks+" CAD assertions.");File.WriteAllText(Path.Combine(folder,"cad-results.txt"),report.ToString(),Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"cad-error.txt"),report+"\r\n"+ex,Encoding.UTF8);return 1;}}
 }
}
